<?php use App\Middleware\Permissions as P; ?>
<div class="page-heading"><div><p class="eyebrow">INVENTORY STRUCTURE</p><h1>Categories &amp; item types</h1><p class="text-secondary">Category → Subcategory → Item Type → Serialized Assets. Drag the handles to reorder siblings.</p></div><?php if (P::allows('inventory.edit')): ?><div class="page-actions"><a href="/inventory/category/add" data-workspace class="btn">Add category / subcategory</a><a href="/inventory/item-type/add" data-workspace class="btn btn-primary">Add item type</a></div><?php endif; ?></div>
<div class="category-tree" data-sortable-list="folders" data-parent-id="" data-can-sort="<?= P::allows('inventory.edit')?'1':'0' ?>">
<?php $roots = array_filter($folders,fn(array $f): bool => $f['parent_id']===null); if (!$roots): ?><section class="card floating-card" data-card-key="category-empty"><h2 class="floating-label">Build your shop inventory</h2><div class="card-body"><p>Add Lighting, Audio, Rigging, and Production categories, then their subcategories and item types.</p></div></section><?php endif; ?>
<?php foreach ($roots as $category): ?><section class="card floating-card sortable-item" data-card-key="category-<?= e($category['id']) ?>" data-id="<?= e($category['id']) ?>"><h2 class="floating-label"><span class="material-symbols-rounded drag-handle" aria-label="Drag to reorder">drag_indicator</span><?= e($category['name']) ?></h2><div class="card-body" data-sortable-list="folders" data-parent-id="<?= e($category['id']) ?>">
<?php foreach (array_filter($folders,fn(array $f): bool => $f['parent_id']===$category['id']) as $subcategory): ?><div class="subcategory sortable-item" data-id="<?= e($subcategory['id']) ?>"><h3><span class="material-symbols-rounded drag-handle" aria-label="Drag to reorder">drag_indicator</span><?= e($subcategory['name']) ?></h3><div data-sortable-list="item_types" data-parent-id="<?= e($subcategory['id']) ?>"><?php foreach (array_filter($types,fn(array $t): bool => $t['folder_id']===$subcategory['id']) as $type): ?><div class="item-type-row sortable-item" data-id="<?= e($type['id']) ?>"><span class="material-symbols-rounded drag-handle" aria-label="Drag to reorder">drag_indicator</span><strong><?= e($type['name']) ?></strong><span class="badge bg-secondary-lt"><?= e($type['prefix']) ?></span><a href="/inventory?type=<?= e($type['id']) ?>" data-workspace>View assets</a></div><?php endforeach; ?></div></div><?php endforeach; ?></div></section><?php endforeach; ?></div>
<?php $resource='categories';$tableTitle='Category records';require ROOT . '/app/Views/partials/table.php'; ?>
<?php if (P::allows('inventory.edit')): ?><section class="card floating-card" data-card-key="manage-taxonomy"><h2 class="floating-label">Manage inventory structure</h2><div class="card-body"><div class="form-grid">
<div><h3>Categories &amp; subcategories</h3><?php foreach ($folders as $folder): ?><a class="record-row" href="/inventory/category/<?= e($folder['id']) ?>/edit" data-workspace><?= e($folder['name']) ?><span class="material-symbols-rounded" aria-hidden="true">edit</span></a><?php endforeach; ?></div>
<div><h3>Item types</h3><?php foreach ($types as $type): ?><a class="record-row" href="/inventory/item-type/<?= e($type['id']) ?>/edit" data-workspace><?= e($type['name']) ?><span class="material-symbols-rounded" aria-hidden="true">edit</span></a><?php endforeach; ?></div></div></div></section><?php endif; ?>
